-- Scrutiny rule refresh (2026-07-13): corporate/non-corporate entity split, removal of
-- analytical (%/ratio/spike) and physical-vouching rules, human-style query text, and the
-- practical rules added for the Raywings LLP query set. Idempotent: re-running is safe.

update scrutiny_rules set is_active=false where rule_id in ('RAT-001','RAT-003','RAT-004','RAT-005','RAT-006','RAT-007','EXP-002','EXP-007','PROV-002','PROV-005','BKR-006','SALES-001','SALES-006','COMP-001','PAY-004','RPT-001','RPT-002','BKR-003','SALES-002','SALES-003','DEBT-002','TDS-005','TDS-006','TDS-007');
update scrutiny_rules set applicable_to='["corporate"]'::jsonb where rule_id in ('CAP-001','CAP-002','CAP-003','CAP-006','CAP-007','LOAN-001','LOAN-002','LOAN-004','LOAN-006','RPT-004','RPT-005','RPT-006','RPT-007','PAY-006');
update scrutiny_rules set applicable_to='["non_corporate"]'::jsonb where rule_id in ('PAY-007');
update scrutiny_rules set applicable_to='["corporate","non_corporate"]'::jsonb where rule_id not in ('RPT-004','RPT-005','TDS-005','RAT-004','RPT-002','CAP-003','RPT-006','RAT-001','BKR-006','RAT-006','SALES-002','CAP-006','CAP-007','TDS-007','PAY-007','EXP-007','TDS-006','DEBT-002','SALES-003','EXP-002','RPT-007','RAT-007','BKR-003','LOAN-002','COMP-001','RPT-001','PROV-005','LOAN-001','SALES-001','PROV-002','LOAN-006','PAY-004','RAT-005','CAP-001','CAP-002','LOAN-004','SALES-006','PAY-006','RAT-003');
update scrutiny_rules set audit_query_template='Asset ledger "{account}" shows a credit (abnormal) balance of â‚¹{amount}. Why does an asset head carry a credit balance â€” is a receipt/contra wrongly posted here, or is this actually a payable? Reclassify to the correct head or confirm the balance.' where rule_id='BKR-001';
update scrutiny_rules set audit_query_template='Suspense account "{account}" still carries â‚¹{amount} at year end. Identify the unposted entries and clear the suspense to the correct ledgers before finalisation â€” nothing should remain in Suspense on the closing BS.' where rule_id='BKR-002';
update scrutiny_rules set audit_query_template='Cash-in-hand closed at â‚¹{amount} on {date}, above the â‚¹2L limit. Why is such a high cash balance held? Verify no single receipt breaches Sec 269ST and that the physical cash is supported.' where rule_id='CASH-001';
update scrutiny_rules set audit_query_template='Cash payment of â‚¹{amount} in "{account}" on {date} exceeds â‚¹20,000. This attracts disallowance u/s 40A(3) â€” confirm the payee/nature and whether it should be routed through bank; else flag for disallowance.' where rule_id='CASH-002';
update scrutiny_rules set audit_query_template='Cash receipt of â‚¹{amount} in "{account}" on {date} exceeds â‚¹2L, hitting Sec 269ST (penalty equals the amount received). Confirm the payer and route the receipt through banking channel; do not accept â‚¹2L or more in cash.' where rule_id='CASH-003';
update scrutiny_rules set audit_query_template='Fixed asset / capital item appears paid in cash (â‚¹{amount}) via "{account}". Cash capex above â‚¹10,000 is not eligible for depreciation u/s 43(1) â€” confirm the payment mode and route it through bank.' where rule_id='CASH-004';
update scrutiny_rules set audit_query_template='Purchase/expense of â‚¹{amount} on {date} in "{account}" has no corresponding creditor/party entry. Confirm the supplier and post the payable, or verify it was a direct cash/bank payment.' where rule_id='EXP-001';
update scrutiny_rules set audit_query_template='Repair/maintenance of â‚¹{amount} booked in "{account}" exceeds â‚¹5L. Is this a revenue repair or a capital improvement extending the asset''s life? If capital, transfer to Fixed Assets and provide depreciation instead of full write-off.' where rule_id='EXP-003';
update scrutiny_rules set audit_query_template='Expense of â‚¹{amount} in "{account}" ("{narration}") appears personal in nature. Confirm the business purpose â€” if personal, disallow / transfer to partner/director drawings; do not claim as business expense.' where rule_id='EXP-004';
update scrutiny_rules set audit_query_template='Expense of â‚¹{amount} dated {date} in "{account}" is booked after the year-end cut-off. Confirm it pertains to this year (accrue) or the next year (reverse) â€” correct the period so expenses are not misstated.' where rule_id='EXP-006';
update scrutiny_rules set audit_query_template='Debtor "{account}" (â‚¹{amount}) is outstanding beyond {threshold} days with no receipts. Is this recoverable? Obtain balance confirmation and, if doubtful, make provision / write off as bad debt.' where rule_id='DEBT-001';
update scrutiny_rules set audit_query_template='Sales of â‚¹{amount} recorded with no corresponding debtor/receipt entry. Was this a cash sale, or is the party ledger missing? Post the receivable so the sale is traceable to a party.' where rule_id='DEBT-004';
update scrutiny_rules set audit_query_template='Debtor "{account}" carries a credit balance of â‚¹{amount}. Is this an advance received from the customer or an excess receipt? Reclassify to Advances-from-Customers (current liability); do not net it against debtors.' where rule_id='DEBT-005';
update scrutiny_rules set audit_query_template='Creditor "{account}" shows a debit balance of â‚¹{amount}. Why does a payable show debit â€” is it an advance paid to the supplier, or a debit left after TDS/short payment? If not genuinely receivable, transfer it to kasar/round-off; if an advance, reclassify to Advances.' where rule_id='CRED-001';
update scrutiny_rules set audit_query_template='Creditor "{account}" (â‚¹{amount}) has been outstanding beyond {threshold} days with no movement. Confirm the liability still subsists â€” if the party is settled or untraceable, the cessation is taxable u/s 41(1); else obtain balance confirmation.' where rule_id='CRED-002';
update scrutiny_rules set audit_query_template='MSME creditor "{account}" (â‚¹{amount}) appears unpaid beyond 45 days. Confirm MSME status (Udyam) â€” interest u/s 16 of the MSMED Act is disallowable u/s 43B(h); disclose in the MSME note and add back if unpaid.' where rule_id='CRED-003';
update scrutiny_rules set audit_query_template='Creditor "{account}" (â‚¹{amount}) has no matching purchase/expense booked against it. Why is this payable standing â€” is a purchase invoice unrecorded, or is this a wrong/duplicate entry? Match it to the underlying bill.' where rule_id='CRED-004';
update scrutiny_rules set audit_query_template='Loan "{account}" shows repayment but no interest charged. Is it genuinely interest-free? If interest is due, provide it and deduct TDS u/s 194A; also confirm the repayment was not made in cash of â‚¹20,000 or more (Sec 269T).' where rule_id='LOAN-003';
update scrutiny_rules set audit_query_template='Employee/staff advance "{account}" (â‚¹{amount}) shows no recovery during the year. Confirm the sanction and recovery schedule and that it is genuinely recoverable; if long-outstanding, recover or provide.' where rule_id='LOAN-007';
update scrutiny_rules set audit_query_template='"{account}" of â‚¹{amount} looks like a capital item (furniture/equipment) booked under an office/indirect expense head. Why is a fixed asset recorded in expense instead of Fixed Assets? Capitalise it and charge depreciation.' where rule_id='FA-001';
update scrutiny_rules set audit_query_template='Asset(s) in "{account}" are fully depreciated yet still in the block. Confirm they remain in use; if discarded/sold, retire them and reverse the WDV so the FA register reflects reality.' where rule_id='FA-006';
update scrutiny_rules set audit_query_template='Stock ledger "{account}" shows a negative balance of â‚¹{amount}. Negative stock is not possible â€” issues exceed receipts. Trace the missing purchase/receipt entry or the wrong stock item and correct the quantity.' where rule_id='INV-001';
update scrutiny_rules set audit_query_template='Inventory item "{account}" (â‚¹{amount}) has not moved for over {threshold} days. Confirm whether it is slow-moving/obsolete and value it at lower of cost or NRV; provide for the shortfall.' where rule_id='INV-002';
update scrutiny_rules set audit_query_template='Goods in transit of â‚¹{amount} in "{account}" at year end. Confirm ownership passed before year end (cut-off) and that the corresponding liability is recorded.' where rule_id='INV-005';
update scrutiny_rules set audit_query_template='Entry in "{account}" is dated {date}, which is post-dated (after the reporting date). Why is a future-dated voucher in this year''s books? Confirm the correct date and move it to the right period.' where rule_id='JE-007';
update scrutiny_rules set audit_query_template='Litigation/legal ledger "{account}" (â‚¹{amount}) with no provision made. Assess the likely outcome â€” if an outflow is probable, provide for it (AS 29 / Ind AS 37); else disclose as a contingent liability.' where rule_id='PROV-004';
update scrutiny_rules set audit_query_template='Share capital in "{account}" moved by â‚¹{amount} during the year. Provide the reason (fresh issue / buy-back / conversion) and confirm the corresponding ROC filing (PAS-3 / SH-7 / MGT) is done.' where rule_id='CAP-001';
update scrutiny_rules set audit_query_template='Dividend of â‚¹{amount} declared in "{account}". Confirm it is out of distributable profits per Sec 123 and that TDS on dividend u/s 194 and the ROC return are in order.' where rule_id='CAP-002';
update scrutiny_rules set audit_query_template='Securities premium in "{account}" moved by â‚¹{amount}. Confirm the utilisation is restricted to the purposes permitted u/s 52 (bonus issue, preliminary expenses, buy-back, premium on redemption).' where rule_id='CAP-003';
update scrutiny_rules set audit_query_template='Buy-back of â‚¹{amount} recorded in "{account}". Confirm Sec 68 limits, board/shareholder approval, and creation of the Capital Redemption Reserve for the nominal value bought back.' where rule_id='CAP-006';
update scrutiny_rules set audit_query_template='Unsecured loan of â‚¹{amount} in "{account}". Confirm the lender, that a board resolution/agreement exists, interest is provided with TDS u/s 194A, and the loan was not accepted/repaid in cash of â‚¹20,000 or more (Sec 269SS / 269T).' where rule_id='LOAN-002';
update scrutiny_rules set audit_query_template='Related-party transactions of â‚¹{amount} identified. Confirm they are disclosed per AS 18 / Ind AS 24 (name, relationship, nature, amount, balance outstanding) in the notes.' where rule_id='RPT-003';
update scrutiny_rules set audit_query_template='Directors'' sitting fee of â‚¹{amount} in "{account}" appears paid without TDS. Sitting fee attracts TDS u/s 194J â€” deduct and deposit it.' where rule_id='PAY-006';
update scrutiny_rules set audit_query_template='Partner remuneration in "{account}" may exceed the Sec 40(b) book-profit limits. Recompute the allowable remuneration against book profit and disallow the excess; confirm it is authorised by the partnership deed.' where rule_id='PAY-007';
insert into scrutiny_rules (rule_id,rule_name,category,detection_level,detection_logic,severity,audit_query_template,is_active,applicable_to,root_cause) values ('BKR-DUP-01','Duplicate Same-Party Ledgers in Group','BKR','account','{"check":"duplicate_ledger","min_similarity":0.8}','medium','Ledgers {account} appear to be the same party recorded twice in one group - merge them if duplicate.',true,'["corporate","non_corporate"]'::jsonb,'Raywings practical query 2026-07-13') on conflict (rule_id) do update set detection_logic=excluded.detection_logic, audit_query_template=excluded.audit_query_template, is_active=true, applicable_to=excluded.applicable_to;
insert into scrutiny_rules (rule_id,rule_name,category,detection_level,detection_logic,severity,audit_query_template,is_active,applicable_to,root_cause) values ('PROV-DR-01','Outstanding Expense Ledger With Debit Balance','PROV','account','{"check":"expr","grain":"account","scope":{"parent_group_keywords":["outstanding exp","expenses payable","expense payable"],"nonzero":true},"where":[{"field":"closing","op":">","value":0}]}','medium','Outstanding-expense ledger {account} shows a debit balance of {amount} - is this an advance given or an expense yet to be booked? Reclassify accordingly.',true,'["corporate","non_corporate"]'::jsonb,'Raywings practical query 2026-07-13') on conflict (rule_id) do update set detection_logic=excluded.detection_logic, audit_query_template=excluded.audit_query_template, is_active=true, applicable_to=excluded.applicable_to;
insert into scrutiny_rules (rule_id,rule_name,category,detection_level,detection_logic,severity,audit_query_template,is_active,applicable_to,root_cause) values ('EXP-MISCLASS-01','Welfare Fund Clubbed in Labour/Staff Expense','EXP','account','{"check":"keyword_balance","keywords":["labour welfare","staff welfare","welfare fund"]}','low','{account} of {amount} relates to a welfare fund - record it as a separate Labour Welfare Fund ledger and create the corresponding liability; do not club with Labour/Staff Expense.',true,'["corporate","non_corporate"]'::jsonb,'Raywings practical query 2026-07-13') on conflict (rule_id) do update set detection_logic=excluded.detection_logic, audit_query_template=excluded.audit_query_template, is_active=true, applicable_to=excluded.applicable_to;

-- Supersede the 5 handler-less tds_missing rules: TDS-XLEG-01 (tds_shortfall, cross-leg,
-- section-aware 194C/194J/194I/194H/194A) already does this properly and is validated.
update scrutiny_rules set is_active=false, root_cause='SUPERSEDED by TDS-XLEG-01 (cross-leg tds_shortfall)' where rule_id in ('TDS-001','TDS-002','TDS-003','TDS-004','PAY-006');
-- ensure directors' sitting fee is picked up by the 194J section of TDS-XLEG-01
update scrutiny_rules set detection_logic = jsonb_set(detection_logic, '{sections,1,keywords}', '["professional","consultanc","technical","audit fee","legal fee","retainer","sitting fee"]'::jsonb) where rule_id='TDS-XLEG-01' and detection_logic->'sections'->1->>'section'='194J';
